```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_rw;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // RecordSeen: mark every id the run considered as seen in the
        // read-write 'seen' store, keyed by id, valued by the run's date.
        // `recorded` counts the ids that were not already present, so the
        // ensures `recorded >= 0` holds trivially (u32 is non-negative).
        let mut recorded: u32 = 0;

        for id in &published.considered {
            if state_rw::get(id).is_none() {
                recorded = recorded.saturating_add(1);
            }
            state_rw::put(id, &published.date);
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

